using NUnit.Framework;using UnityEditor;using UnityEngine;namespace Rootborn.Tests.EditMode.UI{public sealed class SchoolSupportPixelImportTests{[TestCase("Assets/Art/CareerFurniture/Activity31/Activity31_nurse_box_1x1.png",48,96,24,24)][TestCase("Assets/Art/SchoolPixels/sprites/wall_clock.png",32,32,16,16)]public void NativePixelPropsKeepPointSamplingNoMipsAndUncompressedGeometry(string path,int w,int h,int px,int py){var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(s,Is.Not.Null);Assert.That(s.rect.size,Is.EqualTo(new Vector2(w,h)));Assert.That(s.pivot,Is.EqualTo(new Vector2(px,py)));Assert.That(s.pixelsPerUnit,Is.EqualTo(48));Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point),"Pixel props must retain hard square clusters in actual game rendering");Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));}}}